producer-graph.producer_yaml:
schema_version: '1.0'
domain: TEST
base: RAW
keys: [ID]
input: {RAW: {path: ../../raw/raw.csv, types: {ID: int, VALUE: float}}}
columns:
  - {name: ID, type: int, label: Identifier, derivation: RAW.ID}
  - {name: VALUE, type: float, label: Value, derivation: {function: {name: id_float, args: {x: RAW.VALUE}}}}
output: {path: ../../generated/producer.csv, columns: [ID, VALUE], decimals: 2}

producer-graph.consumer_yaml:
schema_version: '1.0'
domain: TEST
base: FIRST
keys: [ID]
input:
  FIRST: {path: ../generated/producer.csv, schema: ../producer/p.yaml}
  SECOND: {path: ../generated/producer.csv, schema: ../producer/./p.yaml}
intermediates: [{id: SECOND_REFERENCE, dataset: SECOND, key: [ID], no_match: null}]
columns:
  - {name: ID, type: int, label: Identifier, derivation: FIRST.ID}
  - {name: FIRST_VALUE, type: float, label: First value, derivation: FIRST.VALUE}
  - {name: SECOND_VALUE, type: float, label: Second value, derivation: SECOND_REFERENCE.VALUE}
  - {name: VALUE, type: float, label: Value, derivation: {compute: {expr: 'FIRST_VALUE + SECOND_VALUE'}}}
output: {path: ../generated/root.csv, columns: [ID, VALUE], decimals: 2}

producer-graph.retained_bridge_yaml:
schema_version: '1.0'
domain: TEST
base: FIRST
keys: [ID]
input: {FIRST: {path: ../generated/producer.csv, schema: ../producer/p.yaml}}
columns:
  - {name: ID, type: int, label: Identifier, derivation: FIRST.ID}
  - {name: VALUE, type: float, label: Value, derivation: FIRST.VALUE}
output: {path: ../generated/left.csv, columns: [ID, VALUE], decimals: 2}

producer-graph.function_yaml:
function: HOST_CALLABLE
description: Installed numeric identity.
params: [{name: x, type: float}]
returns: float
tests:
  - {id: normal, covers: [normal, numeric-comparison], args: {x: 7.25}, result: 7.25}
  - {id: boundary, covers: [boundary], args: {x: 0.0}, result: 0.0}
  - {id: missing, covers: ['short-circuit-missing:x'], args: {x: null}, result: null}

original-specifications.preflight_valid_yaml:
schema_version: '1.0'
domain: TEST
keys: [ID]
input: {SRC: input.csv}
output: {path: output.csv, columns: [ID]}
columns:
  - {name: ID, type: int, derivation: {source: SRC.ID}}

original-specifications.section_order_yaml:
schema_version: "1.0"
domain: TEST
input:
  SRC: {path: src.csv}
  OTHER: {path: other.csv}
keys: [ID, SECTION]
output: {path: result.csv, columns: [ID, SECTION, K, SEQ, V, FINAL, FIRST]}
intermediates:
  - id: P
    dataset: SELF
    key: {K: K}
    order_by: [SELF.SEQ]
    keep: last
    no_match: 0
  - id: F
    dataset: SELF
    key: [K]
    filter: "SECTION = 'first'"
    order_by: [SEQ]
    keep: last
    no_match: null
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: SECTION, type: str}
  - {name: K, type: str, derivation: SRC.K}
  - {name: SEQ, type: int, derivation: SRC.SEQ}
  - {name: V, type: int, derivation: SRC.V}
  - {name: FINAL, type: int, derivation: P.V}
  - {name: FIRST, type: int, derivation: F.V}
rows:
  - id: collected
    dataset: SRC
    derivations:
      SECTION: {literal: first}
  - id: grouped
    dataset: SRC
    group_by: [SRC.K]
    derivations:
      ID: {literal: g}
      SECTION: {literal: second}
      SEQ: {literal: 4}
      V: {compute: {expr: "P.V + 10"}}
  - id: added
    dataset: OTHER
    derivations:
      ID: OTHER.ID
      SECTION: {literal: third}
      K: OTHER.K
      SEQ: {literal: 9}
      V: {compute: {expr: "P.V + 100"}}

original-specifications.duplicate_lookup_yaml:
schema_version: '1.0'
domain: TEST
base: SRC
keys: [ID, PARAM]
input:
  SRC: {path: src.csv, types: {ID: int}}
  DONOR: {path: donor.csv, types: {ID: float, SEQ: int}}
output: {path: result.csv, columns: [ID, PARAM, A, B]}
intermediates:
  - id: P
    dataset: DONOR
    order_by: [DONOR.SEQ]
    keep: first
    no_match: null
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: PARAM, type: str, derivation: {literal: only}}
  - {name: A, type: str, derivation: P.A}
  - {name: B, type: str, derivation: P.B}

original-specifications.lookup_filter_yaml:
schema_version: '1.0'
domain: TEST
base: SRC
keys: [ID, SEQ]
input:
  SRC: {path: src.csv, types: {ID: int, SEQ: int}}
output: {path: result.csv, columns: [ID, SEQ, A, B]}
intermediates:
  - id: P
    dataset: SRC
    key: [ID]
    filter: "SRC.ELIG = 'Y'"
    order_by: [SRC.SEQ]
    keep: last
    no_match: null
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: SEQ, type: int, derivation: SRC.SEQ}
  - {name: A, type: str, derivation: P.A}
  - {name: B, type: str, derivation: P.B}

original-specifications.unicode_case_yaml:
schema_version: '1.0'
domain: TEST
keys: [ID]
input: {SRC: input.csv}
output: {path: output.csv, columns: [ID, UP, LOW, SENT, TITLE]}
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: UP, type: str, derivation: {str_case: {source: SRC.TEXT, to: upper, missing: MiXeD}}}
  - {name: LOW, type: str, derivation: {str_case: {source: SRC.TEXT, to: lower, missing: null}}}
  - {name: SENT, type: str, derivation: {str_case: {source: SRC.TEXT, to: sentence, missing: null}}}
  - {name: TITLE, type: str, derivation: {str_case: {source: SRC.TEXT, to: title, missing: null}}}

original-specifications.lookup_cutoff_yaml:
schema_version: '1.0'
domain: TEST
base: SRC
keys: [ID, SEQ]
input:
  SRC: {path: src.csv, types: {ID: int, SEQ: int, CUT: int}}
  D: {path: donor.csv, types: {ID: int, TIME: int}}
output: {path: result.csv, columns: [ID, SEQ, A, B]}
intermediates:
  - id: P
    dataset: D
    key: [ID]
    filter: "D.TIME < SRC.CUT"
    order_by: [D.TIME]
    keep: last
    no_match: null
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: SEQ, type: int, derivation: SRC.SEQ}
  - {name: A, type: str, derivation: P.A}
  - {name: B, type: str, derivation: P.B}

original-specifications.lookup_alternative_yaml:
schema_version: '1.0'
domain: TEST
base: SRC
keys: [ID, SEQ]
input:
  SRC: {path: src.csv, types: {ID: int, SEQ: int, CUT: int}}
  ALT: {path: alt.csv, types: {ID: int, SEQ: int, CUT: int}}
  D: {path: donor.csv, types: {ID: int, TIME: int}}
output: {path: result.csv, columns: [ID, SEQ, A, B]}
intermediates:
  - id: P
    dataset: D
    key: [ID]
    filter: "D.TIME < ALT.CUT"
    order_by: [D.TIME]
    keep: last
    no_match: null
rows:
  - id: alternate
    dataset: ALT
    derivations: {ID: ALT.ID, SEQ: ALT.SEQ, A: P.A, B: P.B}
columns:
  - {name: ID, type: int}
  - {name: SEQ, type: int}
  - {name: A, type: str}
  - {name: B, type: str}

public-contract.specification_yaml:
schema_version: '1.0'
